package ro.leo.visual;
import android.content.*;import android.media.*;import android.os.*;import android.view.*;import java.util.*;
/** One keypad entry point for music and FM; no polling while hidden. */
public final class NowPlayingActivity extends LeoActivity {
 private final Handler timer=new Handler();private int source;private final Runnable tick=new Runnable(){public void run(){show();timer.postDelayed(this,1000);}};
 protected void onCreate(Bundle b){super.onCreate(b);source=FmService.playing?1:0;}
 protected void onResume(){super.onResume();timer.post(tick);}protected void onPause(){timer.removeCallbacks(tick);super.onPause();}
 private void show(){PlaybackService music=PlaybackService.instance;String title=source==1?(FmService.stationName.isEmpty()?String.format(Locale.ROOT,"%.1f MHz",FmService.frequency/1000f):FmService.stationName):PlaybackService.title;String state=source==1?FmService.state:PlaybackService.state;AudioManager a=(AudioManager)getSystemService(AUDIO_SERVICE);String route="Difuzor";for(AudioDeviceInfo d:a.getDevices(AudioManager.GET_DEVICES_OUTPUTS))if(d.getType()==AudioDeviceInfo.TYPE_BLUETOOTH_A2DP)route="Bluetooth audio";else if(d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADPHONES||d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADSET)route="Căști cu fir";if(source==1&&FmService.speaker)route="Difuzor";
 ArrayList<String> rows=new ArrayList<String>(Arrays.asList((source==1?"Radio FM":"Muzică")+" · "+state,title.isEmpty()?"Nimic în redare":title,source==1?"Volum FM · "+FmService.volume+"%":"Timp · "+MediaActivity.format(music==null?0:music.position())+" / "+MediaActivity.format(music==null?0:music.duration())+"\nVolum · "+a.getStreamVolume(AudioManager.STREAM_MUSIC)+" / "+a.getStreamMaxVolume(AudioManager.STREAM_MUSIC),"Ieșire disponibilă · "+route,"Deschide playerul","Piesa / postul anterior","Piesa / postul următor","Oprește"));if(replaceRows("Acum se redă",rows))return;list("Acum se redă",rows,0,new Choice(){public void pick(int i){if(i==0){source=1-source;show();}else if(i==4)startActivity(new Intent(NowPlayingActivity.this,source==1?FmActivity.class:MediaActivity.class).putExtra("now",true));else if(i==5||i==6){if(source==1){if(FmService.instance!=null)FmService.instance.seek(i==6);}else if(PlaybackService.instance!=null)PlaybackService.instance.next(i==6);}else if(i==7)stopService(new Intent(NowPlayingActivity.this,source==1?FmService.class:PlaybackService.class));}},"Sursă",new Runnable(){public void run(){source=1-source;show();}});}
 public boolean onKeyDown(int key,KeyEvent e){if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){int direction=key==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1;if(source==1){if(FmService.instance!=null)FmService.instance.setVolume(FmService.volume+direction*2);}else ((AudioManager)getSystemService(AUDIO_SERVICE)).adjustStreamVolume(AudioManager.STREAM_MUSIC,direction,0);show();return true;}return super.onKeyDown(key,e);}
}
